const item = items[0];
const json = item.json || {};
const query = json.query && typeof json.query === 'object' ? json.query : {};
const body = json.body && typeof json.body === 'object' ? json.body : json;
const binary = item.binary || {};
const firstBinaryKey = Object.keys(binary)[0] || '';
const firstBinary = firstBinaryKey ? binary[firstBinaryKey] || {} : {};
const operation = String(body.operation ?? query.operation ?? 'insert').trim().toLowerCase();
const rawText = String(body.rawText ?? '').trim();
const sourceType = String(body.sourceType ?? (firstBinaryKey ? 'file' : (rawText ? 'text' : 'text'))).trim().toLowerCase();
const fileName = String(body.fileName ?? firstBinary.fileName ?? '').trim();
const mimeType = String(body.mimeType ?? firstBinary.mimeType ?? '').trim();
const effectiveTitle = String(body.title ?? body.name ?? firstBinary.fileName ?? 'Untitled knowledge source').trim();
const sourceReference = String(body.storagePath ?? body.source ?? (firstBinaryKey ? 'upload:' + (firstBinary.fileName ?? 'binary-file') : 'manual-text')).trim();
const fileTypeLabel = String(body.fileType ?? firstBinary.fileExtension ?? firstBinary.mimeType ?? (sourceType === 'file' ? 'file' : 'text')).trim().toLowerCase();
item.json = { ...json, operation, documentId: String(body.documentId ?? body.sourceId ?? '').trim(), sourceType, rawText, storagePath: String(body.storagePath ?? '').trim(), binaryFieldName: firstBinaryKey, fileName, mimeType, effectiveTitle, sourceReference, fileTypeLabel, hasBinaryUpload: Object.keys(binary).length > 0 };
return [item];

const item = items[0];
const data = item.json || {};
const allowedOps = ['list', 'get', 'insert', 'update', 'delete'];
const normalizedOperation = allowedOps.includes(data.operation) ? data.operation : 'insert';
const fallbackUuid = () => {
  const template = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx';
  return template.replace(/[xy]/g, (char) => {
    const rand = Math.floor(Math.random() * 16);
    const value = char === 'x' ? rand : (rand & 0x3) | 0x8;
    return value.toString(16);
  });
};
const generatedId = (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') ? globalThis.crypto.randomUUID() : fallbackUuid();
const normalizedId = data.documentId && data.documentId.length ? data.documentId : generatedId;
const extensionSource = String(data.fileName || data.mimeType || data.fileTypeLabel || '').toLowerCase();
let extractionMode = 'text';
if (extensionSource.includes('.pdf') || extensionSource.includes('application/pdf')) extractionMode = 'pdf';
else if (extensionSource.includes('.json') || extensionSource.includes('application/json')) extractionMode = 'fromJson';
else if (extensionSource.includes('.csv') || extensionSource.includes('text/csv')) extractionMode = 'csv';
item.json = { ...data, operation: normalizedOperation, documentId: normalizedId, extractionMode };
return [item];

const requested = $('Load Requested Source Row').first()?.json ?? null;
const chunks = items.filter(({ json }) => json && json.id).map(({ json }) => ({ id: json.id, chunkIndex: json.chunk_index, metadata: json.metadata, preview: String(json.content ?? '').slice(0, 220) }));
return [{ json: { ok: true, operation: 'get', document: requested && requested.id ? { id: requested.id, title: requested.name, source: requested.source, sourceType: requested.source_type, fileType: requested.file_type, fileName: requested.file_name, storagePath: requested.storage_path, summary: requested.summary, status: requested.status, createdAt: requested.created_at, updatedAt: requested.updated_at } : null, chunkCount: chunks.length, chunks } }];

const base = items[0]?.json ?? $('Route Content Type For Write').first().json;
const rawAgent = String(base.output ?? '').trim().replace(/^```json\s*/i, '').replace(/\s*```$/i, '');
let parsed = {};
try { parsed = JSON.parse(rawAgent); } catch {}
const rawText = String(base.rawText ?? '').trim();
const summaryFallback = rawText ? rawText.slice(0, 220) : '';
const suggestedTitle = String(parsed.suggestedTitle ?? base.effectiveTitle ?? 'Untitled knowledge source').trim();
const summary = String(parsed.summary ?? summaryFallback).trim();
const keywords = Array.isArray(parsed.keywords) ? parsed.keywords.map((v) => String(v).trim()).filter(Boolean) : [];
return [{ json: { ...$('Route Content Type For Write').first().json, suggestedTitle, summary, keywords } }];

const operation = $('Ensure Document Identity').first().json.operation;
const parseNode = $('Parse Text Knowledge Metadata').first().json;
let row = {};
try { row = operation === 'update' ? $('Update Text Source Row').first().json : $('Create Text Source Row').first().json; } catch (error) { row = {}; }
const chunkItems = items.filter(({ json }) => json && Object.keys(json).length);
const chunkCount = chunkItems.length;
return [{ json: { ok: true, operation, document: { id: row.id ?? parseNode.documentId, title: row.name ?? parseNode.suggestedTitle ?? parseNode.effectiveTitle, source: row.source ?? parseNode.sourceReference, sourceType: row.source_type ?? 'text', fileType: row.file_type ?? 'text', fileName: row.file_name ?? null, storagePath: row.storage_path ?? null, summary: row.summary ?? parseNode.summary ?? '', status: row.status ?? 'indexed' }, chunkCount, aiSummary: parseNode.summary || '', keywords: parseNode.keywords || [], message: operation === 'update' ? 'Text knowledge source updated and re-indexed.' : 'Text knowledge source inserted and indexed.' } }];

const candidateNodes = ['Extract PDF Text For Metadata', 'Extract JSON Text For Metadata', 'Extract CSV Text For Metadata', 'Extract Plain Text For Metadata'];
let extracted = {};
for (const nodeName of candidateNodes) {
  try {
    const candidate = $(nodeName).first();
    if (candidate?.json && Object.keys(candidate.json).length > 0) {
      extracted = candidate.json;
      break;
    }
  } catch (error) {}
}
let base = {};
try {
  base = $('Normalize Uploaded File Binary').first()?.json ?? {};
} catch (error) {
  base = $('Route Content Type For Write').first()?.json ?? {};
}
let text = '';
if (typeof extracted.text === 'string' && extracted.text.trim()) {
  text = extracted.text;
} else if (typeof extracted.data === 'string' && extracted.data.trim()) {
  text = extracted.data;
} else if (typeof extracted.content === 'string' && extracted.content.trim()) {
  text = extracted.content;
} else {
  text = JSON.stringify(extracted || {}).slice(0, 5000);
}
return [{ json: { ...base, extractedText: text.slice(0, 5000) } }];

const base = items[0]?.json ?? $('Prepare File Metadata Context').first().json;
const rawAgent = String(base.output ?? '').trim().replace(/^```json\s*/i, '').replace(/\s*```$/i, '');
let parsed = {};
try { parsed = JSON.parse(rawAgent); } catch {}
const extractedText = String(base.extractedText ?? '').trim();
const summaryFallback = extractedText ? extractedText.slice(0, 220) : '';
return [{ json: { ...$('Prepare File Metadata Context').first().json, suggestedTitle: String(parsed.suggestedTitle ?? base.effectiveTitle ?? base.fileName ?? 'Untitled upload').trim(), summary: String(parsed.summary ?? summaryFallback).trim(), keywords: Array.isArray(parsed.keywords) ? parsed.keywords.map((v) => String(v).trim()).filter(Boolean) : [] } }];

const operation = $('Ensure Document Identity').first().json.operation;
const parseNode = $('Parse File Knowledge Metadata').first().json;
let row = {};
try { row = operation === 'update' ? $('Update File Source Row').first().json : $('Create File Source Row').first().json; } catch (error) { row = {}; }
const chunkItems = items.filter(({ json }) => json && Object.keys(json).length);
const chunkCount = chunkItems.length;
