const item = items[0];
const binary = item.binary || {};
const firstKey = Object.keys(binary)[0] || '';
if (firstKey && firstKey !== 'data') {
  item.binary = { data: binary[firstKey] };
}
item.json = { ...item.json, normalizedBinaryField: 'data', originalBinaryField: firstKey || 'data' };
return [item];

const parseNode = $('Parse File Knowledge Metadata').first().json;
let row = {};
try {
  const updateRow = $('Update File Source Row').first()?.json;
  if (updateRow && Object.keys(updateRow).length) row = updateRow;
} catch (error) {}
if (!row || !Object.keys(row).length) {
  try {
    const createRow = $('Create File Source Row').first()?.json;
    if (createRow && Object.keys(createRow).length) row = createRow;
  } catch (error) {}
}
return [{ json: {
  ...parseNode,
  resolvedDocumentId: row.id ?? parseNode.documentId,
  resolvedTitle: row.name ?? parseNode.suggestedTitle ?? parseNode.effectiveTitle,
  resolvedSource: row.source ?? parseNode.sourceReference,
  resolvedFileName: row.file_name ?? parseNode.fileName ?? null,
  resolvedStoragePath: row.storage_path ?? parseNode.storagePath ?? parseNode.sourceReference ?? null,
  resolvedSummary: row.summary ?? parseNode.summary ?? '',
  resolvedStatus: row.status ?? 'indexed'
} }];

